export interface components {
  schemas: {
    /** @description 统一成功信封；`data` 的形状见每条路由的 `x-returns` */
    Envelope: {
      data: unknown
      trace_id: string
    }
    Error: {
      /** @enum {string} */
      code:
        | 'invalid_input'
        | 'unauthenticated'
        | 'forbidden'
        | 'sod_violation'
        | 'not_found'
        | 'conflict'
        | 'idempotency_conflict'
        | 'similar_exists'
        | 'stale_record'
        | 'snapshot_mismatch'
        | 'budget_exhausted'
        | 'halted'
        | 'not_approved'
        | 'connection_not_allowed'
        | 'policy_tightened'
        | 'authorization_check_failed'
        | 'provenance_missing'
        | 'unknown_outcome'
        | 'provider_unavailable'
        | 'residency_blocked'
        | 'rate_limited'
        | 'timeout'
        | 'provider_error'
        | 'internal'
        | 'not_implemented'
      message: string
      details?: unknown
      trace_id: string
    }
    WsFrame:
      | {
          /** @enum {string} */
          type: 'TEXT' | 'TOOL_CALL' | 'STATE' | 'CUSTOM'
          /** @description 事件日志 id（ulid）；重连时当 since */
          id: string
          /** @description 事件日志里的原始类型名，如 approval.decided */
          name: string
          /** Format: date-time */
          at: string
          subject?: {
            type: string
            id: string
          }
          run_id?: string
          trace_id?: string
        }
      | {
          /** @constant */
          type: 'CONTROL'
          /** @enum {string} */
          name: 'ready' | 'error' | 'halted' | 'dropped' | 'pong' | 'closing'
          /** Format: date-time */
          at: string
          detail?: Record<string, never>
        }
    WsClientMessage:
      | {
          /** @constant */
          op: 'subscribe'
          /** @description 31 §3.1：一次连接一个 Assignment */
          assignment_id: string
          /** @description 断线重连补拉：上次收到的最后一条事件 id */
          since?: string
          /** @description 事件类型前缀（approval. / change. …）；不给用默认集合 */
          types?: string[]
        }
      | {
          /** @constant */
          op: 'ping'
        }
  }
  responses: never
  parameters: never
  requestBodies: never
  headers: never
  pathItems: never
}
